deleted = 0

    AND code = #{code}


    AND name LIKE CONCAT('%', #{name}, '%')


    AND status = #{status}

mapper.select:
SELECT 
FROM act_activity
WHERE deleted = 0 AND status = 'SCHEDULED' AND schedule_publish_at IS NOT NULL
  AND schedule_publish_at <= #{now}
ORDER BY schedule_publish_at ASC, id ASC
LIMIT #{limit}

SELECT 
FROM act_activity
WHERE deleted = 0 AND status = 'PUBLISHED' AND schedule_offline_at IS NOT NULL
  AND schedule_offline_at <= #{now}
ORDER BY schedule_offline_at ASC, id ASC
LIMIT #{limit}
